 "content": "def transform(grid):
    """Count the two vertical orientations of 4-cell T motifs.

    Up-facing T: a single cell above a three-cell bar (color 3).
    Down-facing T: a three-cell bar above a single cell (color 1).
    Encode each count in the four corners of its 3x3 output panel.
    """
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if len(cells) != 4:
                continue
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            shape = {(y - minr, x - minc) for y, x in cells}
            if (maxr - minr, maxc - minc) != (1, 2):
                continue
            if shape == {(0, 1), (1, 0), (1, 1), (1, 2)}:
                up += 1
            elif shape == {(0, 0), (0, 1), (0, 2), (1, 1)}:
                down += 1

    out = [[0] * 6 for _ in range(3)]
    positions = ((0, 0), (0, 2), (2, 0), (2, 2))
    for i in range(min(up, 4)):
        y, x = positions[i]
        out[y][x] = 3
    for i in range(min(down, 4)):
        y, x = positions[i]
        out[y][x + 3] = 1
    return out
